    iot = IoT::getInstance();
    iot->setControllerName("myPhoton");
    iot->begin();

    // Create your device
    PseudoDevice *guestMode = new PseudoDevice();

    // Add it to IoT
    iot->addDevice(guestMode);
}

void loop() {
    iot->loop();
}
```

